function UICommonBuyItemDialog:Awake()
    CfUtils.SetActive(self.Buy,true)
    CfUtils.SetActive(self.Buy2,false)
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.Bg, Bind(self, self.OnBtnClose))
    self._executeJumpEvent = Events.AddListener(Constants.EventNames.EXECUTE_JUMP, Bind(self, self.ExecuteJumpEventHandler))
    local argument = self.controller.Argument.parameters
    print(table.dump(argument))
    if not argument then
        return
    end
    if not isNull(self.GoodsBg) then
        self.ImgNumBg2 = self.GoodsBg.transform.parent:Find("EquipAndCore/Equip/ImgNumBg2")
    end
    self._goodsId = checkNumber(argument.goodsId)
    self._goodsNum = checkNumber(argument.goodsNum or 1)
    self._consumeGoodsId = checkNumber(argument.consumeGoodsId)
    self._remainTime = checkNumber(argument.remainTime)
    self._consumeNum = checkNumber(argument.consumeNum)
    self._rewards    = checkTable(argument.rewards)
    self._endTime    = checkNumber(argument.endTime)
    self._prices     = checkTable(argument.prices)
    self._levelLimit = checkNumber(argument.levelLimit)
    self._isCloseSDKSecondConfirm  = checkNumber(argument.isCloseSDKSecondConfirm)
    self._textLimit  = argument.textLimit
    self._isShowNum = checkBool(argument.isShowNum)
    self._purchaseLimit = checkInt(argument.purchaseLimit)
    if  isNotNull(argument.channelProductId) then
        self._channelProductId = argument.channelProductId
    end
    if argument.haveNum then
        self._haveNum = checkInt(argument.haveNum)
    else
        self._haveNum = GoodsUtils.GetThingNo(self._goodsId)
    end
    if argument.maxHaveNum then
        self._maxHaveNum = checkInt(argument.maxHaveNum)
    end
    if argument.isPayMoney then
        self._isPayMoney = argument.isPayMoney
    end
    self._buyCb = argument.buyCb
    if checkNumber(argument.maxBuyNum) >= 0 then
        self._maxBuyNum = checkNumber(argument.maxBuyNum)
    else
        self._maxBuyNum = MaxBuyNum
    end
    if self._purchaseLimit > 0 then
        self._maxBuyNum = math.min(self._maxBuyNum, self._purchaseLimit)
    end
    self._unlimited = checkBool(argument.unlimited)
    if argument.refreshType then
        self._refreshType = checkInt(argument.refreshType)
    end
    if argument.coinPrices then
        self._coinPrices = checkTable(argument.coinPrices)
    end
    if argument.payPoint and checkNumber(argument.payPoint) ~= 0 then
        self._payPoint = checkInt(argument.payPoint)
    end
    if argument.activityTips then
        self._activityTips = tostring(argument.activityTips)
    end

    local type = GoodsUtils.GetIdType(self._goodsId)
    if type == Constants.IDType.GoodsBattleFood then
        CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
        self._goodsVo = CookingUtils.GetBattleCookingFoodVo(self._goodsId)
    else
        if argument.goodsVo then 
            self._externalGoodsVo = true
            self._goodsVo = argument.goodsVo
        else
            self._goodsVo = goodsConfMgr:GetGoodsVoById(self._goodsId)
        end
    end
    if not self._goodsVo then
        return
    end
    SetButtonAction(self.MaxBut, Bind(self, self.OnBtnMax))
    local btnMaxLongTap = CfUtils.GetOrAddComponent(self.MaxBut.gameObject, QuickLongTapType)
    btnMaxLongTap.onLongTap:AddListener(Bind(self, self.OnLongTapBtnMax))
    SetButtonAction(self.LeastBut, Bind(self, self.OnBtnMin))
    local btnMinLongTap = CfUtils.GetOrAddComponent(self.LeastBut.gameObject, QuickLongTapType)
    btnMinLongTap.onLongTap:AddListener(Bind(self, self.OnLongTapBtnMin))
    SetButtonAction(self.AddImage, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.MinusImage, Bind(self, self.OnBtnReduce))
    SetButtonAction(self.Buy, Bind(self, self.OnBtnBuy))
    SetButtonAction(self.StyleBtnCheck, Bind(self, self.StyleBtnCheckOnClickHandler))

    self.InputFieldNumber.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 1 then
            self._curBuyNum = 1
        elseif num >= self._maxBuyNum then
            self._curBuyNum = self._maxBuyNum
        else
            self._curBuyNum = num
        end
        self:RefreshSelectNum()
    end)

    self:RefreshTopGoods()

    if next(self._prices) ~= nil or self._payPoint then
        self:FillStoreItem()
        return 
    end
    self:FillSelf()

    if self._isShowNum then
        KTool.SetActive(self.BuyNum, false)
    end

    self.isBackDialog = checkBool(argument.isBackDialog)

    -- 鱼竿和线轮
    if type == Constants.IDType.GoodsFishingRod or type == Constants.IDType.GoodsReel then
        KTool.SetActive(self.BuyNum, false)
    end
end

function UICommonBuyItemDialog:RefreshSelectNum()
    self.InputFieldNumber.text = self._curBuyNum

    --更新按钮状态
    local minusStatus = self._curBuyNum <= 1 and 2 or 1
    CfUtils.SetUISwitchImage(self.BtnMinusTenImgBg, minusStatus)
    CfUtils.SetUISwitchText(self.BtnMinusTenText, minusStatus)
    CfUtils.SetUISwitchImage(self.BtnMinusImgBg, minusStatus)
    CfUtils.SetUISwitchImage(self.BtnMinusImg, minusStatus)

    local maxBuyNum = self:GetMaxBuyNum()
    local addStatus = self._curBuyNum >= maxBuyNum and 2 or 1
    CfUtils.SetUISwitchImage(self.BtnAddImgBg, addStatus)
    CfUtils.SetUISwitchImage(self.BtnAddImg, addStatus)
    CfUtils.SetUISwitchImage(self.BtnAddTenImgBg, addStatus)
    CfUtils.SetUISwitchText(self.BtnAddTenText, addStatus)
    
    if self._coinPrices then
        local scr = self:GetExchangeMaterialNodeScr()
        if not isNull(scr) then
            scr:SetBuyNum(self._curBuyNum)
        end
        return 
    end

    if self._payPoint then
        return
    end

    if #self._prices > 0 then
        self:FillItemPrice()
    else
        if self._isPayMoney then
            CfUtils.FillText(self.CurPrice,CfUtils.GetDisplayPrice(self._consumeNum , self._channelProductId) )
        else
            local haveNum = GoodsUtils.GetThingNo(self._consumeGoodsId)
            local consumeNum = tonumber(self._consumeNum) * self._curBuyNum
            if haveNum >= consumeNum then
                CfUtils.FillText(self.CurPrice, string.format("<color=#ffffff>%d</color>", consumeNum))
            else
                CfUtils.FillText(self.CurPrice, string.format("<color=#e71f55>%d</color>", consumeNum))
            end
        end

    end
end

function UICommonBuyItemDialog:FillSelf()
    self:FillGoodsInfo()

    local type = GoodsUtils.GetIdType(self._goodsId)
    if type == Constants.IDType.GoodsBattleFood then
        KTool.SetActive(self.ownNumInfo, true)
        KTool.SetActive(self.BtnCollect, true)
        KTool.SetActive(self.BuyNum, true)
        --KTool.SetActive(self.CookingEffectScroll, true)
        KTool.SetActive(self.TextCookingEffect, true)
        KTool.SetActive(self.Desc4, true)
        KTool.SetActive(self.Desc3, false)
        KTool.SetActive(self.CountdownNode, false)

        CfUtils.SetUISwitchImage(self.ImgCollect, CookingUtils.IsCollectFood(self._goodsId) and 2 or 1)
        self:FillCookingGoodsInfo()
        SetButtonAction(self.BtnCollect, function()
            local isCollect = CookingUtils.IsCollectFood(self._goodsId)
            CookingUtils.SetCollectStatusFood(self._goodsId, not isCollect)
            CfUtils.SetUISwitchImage(self.ImgCollect, CookingUtils.IsCollectFood(self._goodsId) and 2 or 1)
            Events.Broadcast(Constants.EventNames.BattleFoodCollectChange, nil)
        end)
    elseif type == Constants.IDType.GoodsGift then
        self:_RefreshGoodsGift()
    elseif type == Constants.IDType.CharacterCard or 
            type == Constants.IDType.RoleCardCustomize then
        KTool.SetActive(self.GoodNode, false)
        KTool.SetActive(self.ownNumInfo, false)
        KTool.SetActive(self.BtnCollect, false)
        KTool.SetActive(self.BuyNum, self._maxBuyNum > 1)
        KTool.SetActive(self.TextCookingEffect, false)
    else
        KTool.SetActive(self.ownNumInfo, true)
        KTool.SetActive(self.BtnCollect, false)
        KTool.SetActive(self.BuyNum, self._maxBuyNum > 1)
        --KTool.SetActive(self.CookingEffectScroll.gameObject, false)
        KTool.SetActive(self.TextCookingEffect, false)
    end
    self:RefreshSelectNum()

    KTool.SetActive(self.SalesTimeTitle, self._remainTime > 0 or self._endTime > 0)
    if self._remainTime > 0 or self._endTime > 0 then
        self:StartTimeDown()
    end
end

function UICommonBuyItemDialog:StartTimeDown()
    local countDownTime = self._remainTime > 0 and self._remainTime or self._endTime
    local updateTimeStr = function(time)
        local tipStr = localize("活动倒计时：%s")
        if self._remainTime > 0 then
            tipStr = localize("剩余刷新：%s")
        end
        if self._refreshType then
            if checkInt(self._refreshType) >= 1 then
                tipStr = localize("重置倒计时：%s")
            else
                tipStr = localize("下架倒计时：%s")
            end
        end
        CfUtils.FillText(self.SalesTime, string.format(tipStr, CfUtils.GetTimeHMS4(time)))
    end
    updateTimeStr(countDownTime)
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
         updateTimeStr(count)
    end, countDownTime, false, true)
end

--购买的物品信息
function UICommonBuyItemDialog:FillGoodsInfo()
    local goodsType = GoodsUtils.GetIdType(self._goodsId)
    CfUtils.RefeshGoodGo(self.GoodNode, self._goodsId, nil, 2, nil, function() end)

    if self._externalGoodsVo then -- 商城礼包特殊处理
        local icon = self.GoodNode:Find('Container/Icon')
        if isNotNull(icon) then
            CfUtils.FillImage(icon, CfUtils.GetImageFullPath(self._goodsVo.showImage))
        end
    end
    
    CfUtils.SetActive(self.GoodStar, false)
    KTool.SetActive(self.GoodsBg, false)
    if not isNull(self.ImgNumBg2) then
        KTool.SetActive(self.ImgNumBg2.gameObject, false)
    end
    KTool.SetActive(self.DescScroll, true)
    if self._maxHaveNum then
        CfUtils.FillText(self.OwnNum,  checkInt(self._haveNum) .. '/' .. self._maxHaveNum)
    else
        CfUtils.FillText(self.OwnNum, checkInt(self._haveNum))
    end
    CfUtils.FillText(self.Name, self._goodsVo.name)
    if self._goodsNum <= 1 then
        KTool.SetActive(self.TxtNum, false)
    else
        KTool.SetActive(self.TxtNum, true)
        CfUtils.FillText(self.TxtNum, "x" .. self._goodsNum)
    end
    local type    = GoodsUtils.GetIdType(self._goodsId)
    local quality = self._goodsVo.quality
    if type == Constants.IDType.GoodsBattleFood then
        CfUtils.FillText(self.Desc, self._goodsVo.description)
        quality = goodsConfMgr:GetGoodsVoById(self._goodsId).quality
    else
        KTool.SetActive(self.Tips, true)
        CfUtils.FillText(self.Desc, self._goodsVo.description)
        CfUtils.FillText(self.Tips, self._goodsVo.desc)
    end

    
    if type == Constants.IDType.CharacterCard or type == Constants.IDType.RoleCardCustomize then
        KTool.SetActive(self.GoodNode, false)   
        KTool.SetActive(self.ImgArmForce, true)
        KTool.SetActive(self.StyleNode, false)
        KTool.SetActive(self.StyleBtnCheck, true)
        CfUtils.SetActive(self.ArmForcePurchase, true)
        CfUtils.SetActive(self.Attribute, true)
        CfUtils.SetActive(self.ArmRare, true)
        local cardId = self._goodsId
        local cardInfo = nil
        local rare = self._goodsVo.quality
        if type == Constants.IDType.RoleCardCustomize then
            local roleAttributeVo = cardConfMgr:GetCardRobotAttributeVo(self._goodsVo.effectId)
            cardId = roleAttributeVo.cardId
            cardInfo = cardConfMgr:GetCardByRefId(cardId)
            rare = cardConfMgr:GetCardRareByCardId(roleAttributeVo.cardId, roleAttributeVo.advanceLevel)
            local levelTextNode = self.controller.transform:Find('Root/DescribtionGroup/NameNode/TextRoleLevel')
            CfUtils.SetActive(levelTextNode, true)
            CfUtils.FillText(levelTextNode, string.format('Lv%d', checkInt(roleAttributeVo.cardLevel)))
        elseif type == Constants.IDType.CharacterCard then
            cardInfo = cardConfMgr:GetCardByRefId(cardId)
            rare = cardInfo.rare
        end
        local vo = cardConfMgr:GetCardDefaultSkinByCardId(cardId)
        CfUtils.FillImage(self.ImgArmForce, vo.cardHeadList)
        CfUtils.SetUISwitchImage(self.ArmImgRareBg, rare)
        CfUtils.SetUISwitchImage(self.ArmImgRareIcon, rare)
        CfUtils.FillImage(self.AttrImgElement, CardUtils.GetCardAttrIconPath(cardInfo.attributeType))
        local jobVo =  cardConfMgr:GetCardCareerRowByType(cardInfo.career)
        local jobIcon = jobVo.largeIcon
        CfUtils.FillImage(self.ImgCareer, jobIcon)
    elseif type == Constants.IDType.CardSkin then
        KTool.SetActive(self.GoodNode, false)
        KTool.SetActive(self.ImgArmForce, true)
        KTool.SetActive(self.StyleNode, true)
        KTool.SetActive(self.StyleBtnCheck, true)
        CfUtils.SetActive(self.ArmForcePurchase, true)
        CfUtils.SetActive(self.Attribute, false)
        CfUtils.SetActive(self.ArmRare, false)
        local skinVo = cardConfMgr:GetCardSkinBySkinId(self._goodsId)
        CfUtils.FillImage(self.ImgArmForce, skinVo.cardHeadList)
        local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", skinVo.skinId)

        if string.isEmpty(cardSkinVo.version) then
            CfUtils.SetActive(self.ImgBrand, false)
        else
            CfUtils.SetActive(self.ImgBrand, true)
            CfUtils.FillImage(self.ImgBrand, cardSkinVo.version)
        end
        if not CardComponent:IsHasCard(skinVo.roleId) then
            -- 未拥有武装
            CfUtils.FillText(self.Name, self._goodsVo.name .. localize("<color=#5a5a5a><size=36> (暂未获得对应武装)</size></color>"))
        end
    elseif type == Constants.IDType.BattleCardGameCard then
        CfUtils.SetActive(self.GoodNode, false)
        CfUtils.SetActive(self.PokerCardRoot, true)
        self:_RefreshBattleCardNode()
    else
        KTool.SetActive(self.StyleNode, false)
        KTool.SetActive(self.GoodNode, true)
        KTool.SetActive(self.ImgArmForce, false)
        KTool.SetActive(self.StyleBtnCheck, type == Constants.IDType.GoodsCatBlindBox)
        CfUtils.SetActive(self.ArmForcePurchase, false)
     
    end

    if type == Constants.IDType.Equipment then
        KTool.SetActive(self.EquipAndCore, false)
        KTool.SetActive(self.Role, false)
    end

    if not  self._isPayMoney then
        local path = goodsConfMgr:GetPhotoPathById(self._consumeGoodsId)
        CfUtils.FillImage(self.Icon, path)
    else
        KTool.SetActive(self.Icon , false)
    end



    for index = 1, self.GoodAnimNodes.childCount do
        local child = self.GoodAnimNodes:GetChild(index - 1)
        CfUtils.SetUISwitchParticleSystem(child, quality)
    end
    KTool.SetActive(self.GoodAnimNodes, true)
end

--绘制料理的道具
function UICommonBuyItemDialog:FillCookingGoodsInfo()
    local t = {}
    local t1= CookingUtils.GetBattleFoodEffectDesc(self._goodsId)
    local t2 = CfUtils.Split(self._goodsVo.desc, ";")
    --table.insert(t, t1[1])
    for k, v in pairs(t2) do
        table.insert(t, v)
    end
    KTool.SetActive(self.Desc4, false)
    for k, v in pairs(t) do
        local go = self.Desc4.parent.transform:Find("go"..k)
        if not go then 
            go = CfUtils.InstantiateGo(self.Desc4, self.Desc4.parent)
            go.name = "go"..k
        end
        local status = (k == 1 and 2 or 1) 
        --CfUtils.SetUISwitchImage(go.transform:Find("Area/ImgSquare"), status)
        --CfUtils.SetUISwitchText(go.transform:Find("TextdDesc"), status)
        local _t = CfUtils.Split(v, "+")
        if _t then
            CfUtils.FillText(go.transform:Find("TextdDesc1"), _t[1])
            CfUtils.FillText(go.transform:Find("TextdDesc2"), "+".._t[2])
            KTool.SetActive(go.transform:Find("TextdDesc2"), true)
        end
        KTool.SetActive(go, true)
    end
end

function UICommonBuyItemDialog:_RefreshConsumeInfo()
    local isSoldOut = checkNumber(self._maxBuyNum) <= 0 and not self._unlimited
    KTool.SetActive(self.BtnPurchaseGroup, not isSoldOut)
    KTool.SetActive(self.SellOut, isSoldOut)
    if isSoldOut then
        CfUtils.FillText(self.SellOut:Find("Text"), localize("抱歉啦，该商品已售罄了哦！"))
    end

    if self._consumeGoodsId > 0 and not isSoldOut then
        local consumeDt    = GoodsConfMgr:GetGoodsVoById(self._consumeGoodsId)
        CfUtils.FillImage(self.ImgIcon, consumeDt.photoPath)
        local haveNum = GoodsUtils.GetThingNo(self._consumeGoodsId)
        local consumeNum = tonumber(self._consumeNum)
        if haveNum >= consumeNum then
            CfUtils.FillText(self.CurPrice, string.format("<color=#ffffff>%d</color>", consumeNum))
        else
            CfUtils.FillText(self.CurPrice, string.format("<color=#e71f55>%d</color>", consumeNum))
        end
    end
end

function UICommonBuyItemDialog:_OnGetRewardItemByIndex(gridView, index)
    if index < 0 then
        return nil
    end
    local cellNode = gridView:NewListViewItem("Cell")
    local goodNode = cellNode.transform:GetChild(0)
    ---@type GoodNodeMB
    local nodeEnv  = CfUtils.GetLuaScr(goodNode, "Game.Behaviours.GoodNodeMB")
    local rewardDt = self._rewards[index + 1]
    if nodeEnv then
        nodeEnv:Reload({ 
            goodsId = rewardDt.goodsId, 
            isShowNo = true, 
            text = string.format('x%d', rewardDt.num),
            isGift = checkNumber(rewardDt.isSend)  == 1
        })
        nodeEnv:SetClickButtonAction(function()
            local vo = goodsConfMgr:GetGoodsVoById(rewardDt.goodsId)
            if isTable(vo) then
                GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id)
            end
        end)
    end

    local btnCheck = cellNode.transform:Find('BtnCheck')
    if isNotNull(btnCheck) then
        local type = GoodsUtils.GetIdType(rewardDt.goodsId)
        local excludeIds = nil
        local dialogs = UIModule.CurrentScreen.dialogs
        local count = table.count(dialogs)
        -- 获取倒数第二个
        if count >= 2 and dialogs[count - 2] then
            excludeIds = {
                { id = dialogs[count - 2].Argument.id }
            }
        end
        if type == Constants.IDType.CharacterCard then
            CfUtils.SetActive(btnCheck, true)
            SetButtonAction(btnCheck, function ()
                local gachaponUtils = import('Game.Gachapon.GachaponUtils')
                gachaponUtils.OpenDetail(rewardDt.goodsId, excludeIds)
                self:OnBtnClose()
            end)
        elseif type == Constants.IDType.CardSkin then
            CfUtils.SetActive(btnCheck, true)
            SetButtonAction(btnCheck, function ()
                CfUtils.DialogOpen(Constants.UITypeIds.CommonStylePreView, {skinId = rewardDt.goodsId}, excludeIds, true)
                self:OnBtnClose()
            end)
        else
            CfUtils.SetActive(btnCheck, false)
        end
    end
    return cellNode
end

function UICommonBuyItemDialog:_RefreshGoodsGift()
    KTool.SetActive(self.ownNumInfo, false)
    KTool.SetActive(self.BtnCollect, false)
    if self._payPoint then
        KTool.SetActive(self.BuyNum, false)
    else
        KTool.SetActive(self.BuyNum,  self._maxBuyNum > 1)
    end
    KTool.SetActive(self.TextCookingEffect, false)
    KTool.SetActive(self.DescScroll, false)

    if not self.GoodsIconList.IsListViewInit then
        self.GoodsIconList:InitGridView(#self._rewards, Bind(self, self._OnGetRewardItemByIndex))
    else
        GameUtils.ReloadData(self.GoodsIconList, #self._rewards)
    end
    self:_RefreshConsumeInfo()
end


