    local battleCardId = checkInt(self._goodsId)
    if isNull(self.pokerCardNode_) then
        self.pokerCardNode_ = BattleCardGameUtils.LoadBattleCardNode(self.PokerCardRoot)
    end
    BattleCardGameUtils.UpcateBattleCardNode(self.pokerCardNode_, battleCardId)
end


--最多
function UICommonBuyItemDialog:OnBtnMax(PointerEventData, longTap)
    
    if self._curBuyNum >= self._maxBuyNum then
        if not longTap then
            GameUtils.Toast(localize("已经最大数量了"))
        end
        return
    end
    
    local maxBuyNum = self:GetMaxBuyNum()
    if maxBuyNum == 0 or maxBuyNum == self._curBuyNum then
        if not longTap then
            if self._coinPrices then
                self:ShowInsufficientCoinTips()
            else
                self:ShowInsufficientGoodsTips()
            end
        end
        return
    end

    self._curBuyNum = math.min(maxBuyNum, self._curBuyNum + 10)
    self:RefreshSelectNum()
end



--最少
function UICommonBuyItemDialog:OnBtnMin(PointerEventData, longTap)
    if self._curBuyNum <= 1 then
        if not longTap then
            GameUtils.Toast(localize("已经最低数量了"))
        end
        return 
    end
    
    self._curBuyNum = math.max(1, self._curBuyNum - 10)
    self:RefreshSelectNum()
end

function UICommonBuyItemDialog:OnLongTapBtnMax()
    self:OnBtnMax(nil, true)
end

function UICommonBuyItemDialog:OnLongTapBtnMin()
    self:OnBtnMin(nil, true)
end

--增加
function UICommonBuyItemDialog:OnBtnAdd()
    if self._curBuyNum >= self._maxBuyNum then
        GameUtils.Toast(localize("已经最大数量了"))
        return 
    end

    local maxBuyNum = self:GetMaxBuyNum()
    if maxBuyNum < self._curBuyNum + 1 then
        if self._coinPrices then
            self:ShowInsufficientCoinTips()
        else
            self:ShowInsufficientGoodsTips()
        end
    else
        self._curBuyNum = self._curBuyNum + 1
        self:RefreshSelectNum()
    end
end

--减少
function UICommonBuyItemDialog:OnBtnReduce()
    if self._curBuyNum <= 1 then
        GameUtils.Toast(localize("已经最低数量了"))
        return 
    end
    self._curBuyNum = self._curBuyNum - 1
    self:RefreshSelectNum()
end

function UICommonBuyItemDialog:OnBtnClose()
    if self.isBackDialog then
        UIModule.BackDialog()
    else
        UIModule.CloseDialog(self.controller)
    end

end

function UICommonBuyItemDialog:OnBtnBuy()
    if self._curBuyNum < 1 then
        return
    end
    if self._buyCb then
        if self._isPayMoney then
            if tonumber(self._maxBuyNum) > 0 or self._unlimited then
                self._buyCb(self._curBuyNum)
                self:OnBtnClose()
            else
                GameUtils.Toast(localize("商品已售完"))
            end
            return
        end
        if tonumber(self._maxBuyNum) > 0 then
            local haveNum = GoodsUtils.GetThingNo(self._consumeGoodsId)
            local consumeNum = tonumber(self._consumeNum) * self._curBuyNum
            if haveNum >= consumeNum then
                local consumeConf = GoodsConfMgr:GetGoodsVoById(self._consumeGoodsId)
                local productConf = GoodsConfMgr:GetGoodsVoById(self._goodsId)
                GameUtils.SecondConfirm
                (
                        localize("确认花费_Num__Name_购买_Name1_？",{_Num_ = consumeNum, _Name_ = consumeConf.name, _Name1_ = productConf.name}),
                        function()
                            print("self._buyCb=>" , type(self._buyCb))
                            if type(self._buyCb) == "function" then
                                self._buyCb(self._curBuyNum)
                            end
                            self:OnBtnClose()
                        end
                )
            else
                --StoreUtils.OpenGoodsObtainDialog(self._consumeGoodsId, self.controller)
                self:OpenReceiveView(self._consumeGoodsId, consumeNum)
            end
        else
            GameUtils.Toast(localize("商品已售完"))
        end
    end
end

function UICommonBuyItemDialog:StyleBtnCheckOnClickHandler()
    local goodsType = GoodsUtils.GetIdType(self._goodsId)
    local excludeIds = nil
    local dialogs = UIModule.CurrentScreen.dialogs
    local count = table.count(dialogs)
    -- 获取倒数第二个
    if count >= 2 and dialogs[count - 2] then
        excludeIds = {
            { id = dialogs[count - 2].Argument.id }
        }
    end
    if goodsType == Constants.IDType.CharacterCard then
        ---@type GachaponUtils
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        self:OnBtnClose()
        gachaponUtils.OpenDetail(self._goodsId, excludeIds)
    elseif goodsType == Constants.IDType.CardSkin then
        self:OnBtnClose()
        CfUtils.DialogOpen(Constants.UITypeIds.CommonStylePreView, {skinId = self._goodsId}, excludeIds, true)
    elseif goodsType == Constants.IDType.RoleCardCustomize then
        ---@type GachaponUtils
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        self:OnBtnClose()
        gachaponUtils.OpenDetail(self._goodsId, excludeIds)
    elseif goodsType == Constants.IDType.GoodsCatBlindBox then
        self:OnBtnClose()
        CfUtils.DialogOpen(Constants.UITypeIds.CatBallPreviewDialog, {catBallId = self._goodsId}, excludeIds, true)
    end
end

function UICommonBuyItemDialog:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UICommonBuyItemDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UICommonBuyItemDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:ClearTimeDown()
        Events.RemoveListener(Constants.EventNames.EXECUTE_JUMP, self._executeJumpEvent)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UICommonBuyItemDialog:FillStoreItem()
    self:InitOnBtnClick()
    self:FillItemPrice()
    self:FillGoodsInfo()
    self:FillItemContent()
    self:RefreshSelectNum()
    self:FillItemTimeDown()
    self:RefreshTextLimit()
    self:InitExchangeMaterialNode()
end

function UICommonBuyItemDialog:InitOnBtnClick()
    local btns = {
        self.Buy,
        self.BtnBuyLeft
    }
    local btnNum = math.min(#self._prices, 2)
    if self._coinPrices or self._payPoint then
        btnNum = 1
    end
    
    local function OnBtnBuyClick(index)
        if self._curBuyNum < 1 then
            return
        end
        if self._buyCb then
            if tonumber(self._maxBuyNum) > 0 then
                if self._coinPrices then
                    self:CoinBuy()
                    return
                end

                if self._payPoint then
                    self:SDKBuy()
                    return 
                end
                
                local currency = self._prices[index].currency
                local price = self._prices[index].current
                local haveNum = GoodsUtils.GetThingNo(currency)
                local consumeNum = tonumber(price) * self._curBuyNum
                if haveNum >= consumeNum then
                    local consumeConf = GoodsConfMgr:GetGoodsVoById(currency)
                    local productConf = GoodsConfMgr:GetGoodsVoById(self._goodsId)
                    local text = localize("确认花费_Num__Name_购买_Name1_？",{_Num_ = consumeNum, _Name_ = consumeConf.name, _Name1_ = productConf.name})
                    local subText = nil
                    local goodsType = GoodsUtils.GetIdType(self._goodsId)
                    if goodsType == Constants.IDType.CardSkin then
                        local skinVo = cardConfMgr:GetCardSkinBySkinId(self._goodsId)
                        if not CardComponent:IsHasCard(skinVo.roleId) then
                            -- 未拥有武装
                            subText = localize("<color=#e71f55><size=30>（你暂时未获得该皮肤对应的武装，购买后无法配置显示）</size></color>")
                        end
                    end
                    GameUtils.SecondConfirm
                    (
                            text,
                            function()
                                print("self._buyCb ->" , debug.traceback())
                                if type(self._buyCb) == "function" then
                                    self._buyCb(self._prices[index], self._curBuyNum)
                                end
                                self:OnBtnClose()
                            end,
                            nil,
                            subText
                    )
                else
                    self:OpenReceiveView(self._prices[index].currency, consumeNum,function()
                        print("self._buyCb ->" , debug.traceback())
                        if type(self._buyCb) == "function" then
                            self._buyCb(self._prices[index], self._curBuyNum)
                        end
                        self:OnBtnClose()
                    end)
                end
            else
                GameUtils.Toast(localize("商品已售完"))
            end
        end
    end
    
    for i = 1, btnNum do
        SetButtonAction(btns[i], function ()
            OnBtnBuyClick(i)
        end)
    end
    
    SetButtonAction(self.Buy2,function()
        OnBtnBuyClick(1)
    end)
    
    KTool.SetActive(self.LefttNode, #self._prices > 1)
end

function UICommonBuyItemDialog:FillItemPrice()
    if self._coinPrices then
        CfUtils.SetActive(self.Icon, false)
        CfUtils.SetActive(self.CurPrice, false)
        return 
    end
    
    if self._payPoint then  --rmb付费
        CfUtils.SetActive(self.Buy,false)
        CfUtils.SetActive(self.Buy2,true)
        ---@type CommonPrimaryCurrencyBuyButton
        local lua = CfUtils.GetLuaScr(self.Buy2, "Game.UI.Common.CommonPrimaryCurrencyBuyButton")
        lua:Refresh(self._payPoint)
        --CfUtils.SetActive(self.Icon, false)
        --CfUtils.FillText(self.CurPrice, CfUtils.GetDisplayPrice(self._payPoint))
        return
    end
    
    local price = self._prices[1]
    local goodsVo = GoodsConfMgr:GetGoodsVoById(price.currency)
    CfUtils.FillImage(self.Icon, goodsVo.photoPath)
    local haveNum = GoodsUtils.GetThingNo(price.currency)
    local consumeNum = self._curBuyNum * price.current
    if haveNum >= consumeNum then
        CfUtils.FillText(self.CurPrice, string.format("<color=#ffffff>%d</color>", consumeNum))
    else
        CfUtils.FillText(self.CurPrice, string.format("<color=#e71f55>%d</color>", consumeNum))
    end

    if #self._prices > 1 then
        local priceL = self._prices[2]
        local goodsVoL = GoodsConfMgr:GetGoodsVoById(priceL.currency)
        CfUtils.FillImage(self.BuyLeftCurrency, goodsVoL.photoPath)
        local haveNumL = GoodsUtils.GetThingNo(priceL.currency)
        local consumeNumL = self._curBuyNum * self._curBuyNum * priceL.current
        if haveNumL >= consumeNumL then
            CfUtils.FillText(self.BuyLeftPrice, string.format("<color=#ffffff>%d</color>", consumeNumL))
        else
            CfUtils.FillText(self.BuyLeftPrice, string.format("<color=#e71f55>%d</color>", consumeNumL))
        end
    end
    if self._activityTips then
        local countdown = self.BtnPurchaseGroup:Find("Countdown")
        CfUtils.SetActive(countdown, true)
        local text2 = countdown.transform:Find("Text2")
        CfUtils.SetActive(text2, true)
        CfUtils.FillText(text2, self._activityTips)
    end
end

function UICommonBuyItemDialog:FillItemContent()
    if self._coinPrices then
        CfUtils.SetActive(self.ExchangeMaterial, true)
        CfUtils.SetActive(self.DescScroll, false)
        if self._maxBuyNum ~= MaxBuyNum then
            CfUtils.SetActive(self.Stock, true)
            CfUtils.FillText(self.StockTxtNum, self._maxBuyNum)
        else
            CfUtils.SetActive(self.Stock, false)
        end
        
        local scr = self:GetExchangeMaterialNodeScr()
        if not isNull(scr) then
            scr:InitNode(self._coinPrices, self._curBuyNum)
        end
        CfUtils.SetUISwitchText(self.BuyNumTxt, 2)
        CfUtils.SetUISwitchText(self.BuyTxt, 2)
        self.BuyTxt.anchorMax = Vector2.New(0.5, 0.5)
        self.BuyTxt.anchorMin = Vector2.New(0.5, 0.5)
        self.BuyTxt.localPosition = Vector3.New(0, self.BuyTxt.localPosition.y, 0)
        local text = self.BuyTxt:GetComponent(typeof(CS.UnityEngine.UI.Text))
        if isNotNull(text) then
            text.alignment = CS.UnityEngine.TextAnchor.MiddleCenter
        end
    else
        CfUtils.SetActive(self.ExchangeMaterial, false)
        CfUtils.SetActive(self.DescScroll, true)
    end
    
    local type = GoodsUtils.GetIdType(self._goodsId)
    if type == Constants.IDType.GoodsBattleFood then
        KTool.SetActive(self.ownNumInfo, true)
        KTool.SetActive(self.BtnCollect, true)
        KTool.SetActive(self.BuyNum, true)
        --KTool.SetActive(self.CookingEffectScroll, true)
        KTool.SetActive(self.TextCookingEffect, true)

        CfUtils.SetUISwitchImage(self.ImgCollect, CookingUtils.IsCollectFood(self._goodsId) and 2 or 1)
        self:FillCookingGoodsInfo()
        SetButtonAction(self.BtnCollect, function()
            local isCollect = CookingUtils.IsCollectFood(self._goodsId)
            CookingUtils.SetCollectStatusFood(self._goodsId, not isCollect)
            CfUtils.SetUISwitchImage(self.ImgCollect, CookingUtils.IsCollectFood(self._goodsId) and 2 or 1)
            Events.Broadcast(Constants.EventNames.BattleFoodCollectChange, nil)
        end)
    elseif type == Constants.IDType.GoodsGift and #self._rewards > 0 then
        self:_RefreshGoodsGift()
    elseif type == Constants.IDType.CharacterCard or
            type == Constants.IDType.CardSkin or
            type == Constants.IDType.RoleCardCustomize then
        KTool.SetActive(self.ownNumInfo, false)
        KTool.SetActive(self.BtnCollect, false)
        KTool.SetActive(self.BuyNum, self._maxBuyNum > 1)
        KTool.SetActive(self.TextCookingEffect, false)
    elseif type == Constants.IDType.Equipment then
        self:FillEquipmentItemContent()
    else
        local goodsVo = GoodsConfMgr:GetGoodsVoById(self._goodsId)
        KTool.SetActive(self.ownNumInfo, true)
        KTool.SetActive(self.BtnCollect, false)
        if self._payPoint then
            KTool.SetActive(self.BuyNum, false)
        else
            KTool.SetActive(self.BuyNum,  self._maxBuyNum > 1)
        end
        --KTool.SetActive(self.CookingEffectScroll.gameObject, false)
        KTool.SetActive(self.TextCookingEffect, false)
    end
end

function UICommonBuyItemDialog:FillEquipmentItemContent()
    KTool.SetActive(self.ownNumInfo, false)
    KTool.SetActive(self.BtnCollect, false)
    KTool.SetActive(self.BuyNum,  self._maxBuyNum > 1)
    KTool.SetActive(self.TextCookingEffect, false)
    local equipVo = cardConfMgr:GetEquipVoById(self._goodsId)
    local setVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", equipVo.suitId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = cardConfMgr:GetBasicAttr(attrAddVo.attrId)
    CfUtils.SetActive(self.EquipTypeIcon, true)
    CfUtils.FillImage(self.EquipSuitImgIcon, setVo.icon)
    CfUtils.SetActive(self.DescScroll, false)
    CfUtils.SetActive(self.EquipAttribute, true)
    CfUtils.FillText(self.SuitDescTextTitle, setVo.desc)
    CfUtils.FillText(self.MainImgAttributeIcon, attrVo.icon)
    local env = CfUtils.GetLuaScr(self.MainAttrCommonTitleNode.gameObject, "Game.UI.Common.CommonTitleTipsNode")
    if isNotNull(env) then
        env:RefreshUI(attrVo.name)
    end
    CfUtils.FillImage(self.MainImgAttributeIcon, attrVo.icon)
    local goodsVo = goodsConfMgr:GetGoodsVoById(self._goodsId)
    local attrNum = mainEquipAttrVo.attrNum[tostring(goodsVo.quality)]
    --local curNum = tonumber(attrNum.baseValue) + tonumber(attrNum.growValue) * (checkInt(equipDojo.level) + 5 * tonumber(equipDojo.star))
    local curNum = attribute_format(attrAddVo.isConversion, attrNum.baseMin) .. '~' .. attribute_format(attrAddVo.isConversion, attrNum.baseMax)
    CfUtils.FillText(self.MainTextNumber, curNum)
end

function UICommonBuyItemDialog:FillItemTimeDown()
    KTool.SetActive(self.SalesTimeTitle, self._remainTime > 0 or self._endTime > 0)
    if self._remainTime > 0 or self._endTime > 0 then
        self:StartTimeDown()
    end
end

function UICommonBuyItemDialog:OpenReceiveView(goodsId, consumeNum,buyCallback)
    goodsId = checkInt(goodsId)
    if goodsId == Constants.Currency.PayDiamondId then
        local productVo = GoodsConfMgr:GetGoodsVoById(self._goodsId)
        ServerDifferenceMgr:WrapPrimaryCurrencyBuy({currency = goodsId,current = consumeNum, productName = productVo.name},nil,Bind(self,self.RefreshSelectNum))
    elseif goodsId == Constants.Currency.FreeDiamondId then
        if ServerDifferenceMgr:IsSecondaryCurrencyEnable() then
            ---@type CommonCurrencyExchangePopup.InputData
            local data = {
                leftId = Constants.Currency.FreeDiamondId,
                leftNum = consumeNum,
                rightId = self._goodsId,
                rightNum = checkNumber(self._goodsNum) * checkNumber(self._curBuyNum),
                onConfirmClick = buyCallback,
            }
            ServerDifferenceMgr:OpenCurrencyExchangePopup(data)
        else
            local goodsVo = goodsConfMgr:GetGoodsVoById(Constants.Currency.FreeDiamondId)
            GameUtils.SecondConfirm
            (
                    localize("_name_不足, 是否前往充值？", {_name_ = goodsVo.name}),
                    function()
                        OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.TopUp)
                        self:OnBtnClose()
                    end
            )    
        end
    elseif goodsId == Constants.Currency.FilmR or goodsId == Constants.Currency.FilmSRR or goodsId == Constants.Currency.FilmSSR then
        GoodsUtils.ShowCommonLackMaterialDialog({{ goodsId = goodsId, num = consumeNum }})
        self:OnBtnClose()
    else
        local vo = goodsConfMgr:GetGoodsVoById(goodsId)
        GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
    end
end

function UICommonBuyItemDialog:RefreshTopGoods()
    local goodsIds = {}
    if self._coinPrices then
        for k, v in pairs(self._coinPrices) do
            table.insert(goodsIds, GroceryConstants.CoinQuality2GoodsId[checkInt(k)])
        end
        CfUtils.RefreshTopGoods(goodsIds)
        return 
    end
    
    if next(self._prices) then
        for i, v in ipairs(self._prices) do
            if checkInt(v.currency) > 0 then
                table.insert(goodsIds, v.currency)    
            end
        end
    else
        if checkInt(self._consumeGoodsId) > 0  then
            table.insert(goodsIds, self._consumeGoodsId)    
        end
    end
    if self._isPayMoney or self._payPoint then
        CfUtils.RefreshTopGoods({})
    else
        CfUtils.RefreshTopGoods(goodsIds)
    end
end 

function UICommonBuyItemDialog:RefreshTextLimit()
    if self._levelLimit > 0 then
        KTool.SetActive(self.TextLimitNode, true)
        CfUtils.FillText(self.TextLimit, localize("调查官等级Lv._num_", {_num_ = self._levelLimit}))
        if not StoreUtils.CheckPlayerLevelSatisfy(self._levelLimit) then
            KTool.SetActive(self.Buy, false)
            KTool.SetActive(self.SellOut, true)
            CfUtils.FillText(self.SellOut:Find("Text"), localize("调查官等级不足"))
        end
    elseif self._textLimit then
        KTool.SetActive(self.TextLimitNode, true)
        CfUtils.FillText(self.TextLimit, self._textLimit)
    else
        KTool.SetActive(self.TextLimitNode, false)
    end
end

function UICommonBuyItemDialog:InitExchangeMaterialNode()
    if not self._coinPrices then return end
    
    -- 进入时不需要选中物品
    local scr = self:GetExchangeMaterialNodeScr()
    scr:ClearSelectedItem()
end

---@return CommonExchangeMaterialNode
function UICommonBuyItemDialog:GetExchangeMaterialNodeScr()
    local scr = CfUtils.GetLuaScr(self.ExchangeMaterial, "Game.UI.Common.CommonExchangeMaterialNode")
    return scr
end

function UICommonBuyItemDialog:CoinBuy()
    local scr = self:GetExchangeMaterialNodeScr()
    if not isNull(scr) then
        local isEnough = scr:CheckItemEnough()
        if isEnough then
            local productConf = goodsConfMgr:GetGoodsVoById(self._goodsId)
            local num = self._goodsNum > 1 and 'x'..self._goodsNum or ''
            local tips = localize("确认<color=#e71f55>消耗</color>以下核心兑换_num_个[_name1__num2_]？",{_num_ = self._curBuyNum, _name1_ = productConf.name, _num2_ = num})
            local price = scr:GetItemsCost()    
            GameUtils.SecondConfirm
            (
                    tips,
                    function()
                        if type(self._buyCb) == "function" then
                            local scr = self:GetExchangeMaterialNodeScr()
                            if not isNull(scr) then
                                local price = scr:GetItemsCost() 
                                self._buyCb(price, self._curBuyNum)
                            end
                        end
                        self:OnBtnClose()
                    end,
                    nil,
                    nil,
                    6,
                    price
            )
        else
            self:ShowInsufficientCoinTips()
        end
    end
end

function UICommonBuyItemDialog:ShowInsufficientCoinTips()
    local currency = GroceryConstants.CoinQuality2GoodsId[checkInt(self._prices[1].currency)]
    local goodsVo = goodsConfMgr:GetGoodsVoById(currency)
    GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
end

function UICommonBuyItemDialog:ShowInsufficientGoodsTips()
    if self._consumeGoodsId > 0 then
        local goodsVo = goodsConfMgr:GetGoodsVoById(self._consumeGoodsId) or {}
        GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
        return 
    end
    
    local payMaxNum = 0
    local currency = nil
    for _, v in ipairs(self._prices) do
        local haveNum = GoodsUtils.GetThingNo(v.currency)
        local num = math.floor(haveNum / v.current)
        if num >= payMaxNum then
            payMaxNum = num
            currency = v.currency
        end
    end
    local goodsVo = goodsConfMgr:GetGoodsVoById(currency) or {}
    GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
end

function UICommonBuyItemDialog:SDKBuy()
    local productConf = GoodsConfMgr:GetGoodsVoById(self._goodsId)
    local subTitle = nil
    local idType = GoodsUtils.GetIdType(self._goodsId)
    if idType == Constants.IDType.CardSkin then
        local skinVo = cardConfMgr:GetCardSkinBySkinId(self._goodsId)
        if not CardComponent:IsHasCard(skinVo.roleId) then
            -- 卡牌未拥有
            subTitle = localize("<color=#ff0000>(你暂未获得对应的武装，购买后无法配置显示)</color>")
        end
    end
    if self._isCloseSDKSecondConfirm then
        self._buyCb()
        self:OnBtnClose()
        return
    end
    GameUtils.SecondConfirm
    (
            localize("确认花费_num_购买_Name1_？",{_num_ = CfUtils.GetDisplayPrice(self._payPoint , self._channelProductId) , _Name1_ = productConf.name}),
            function()
                if type(self._buyCb) == "function" then
                    local scr = self:GetExchangeMaterialNodeScr()
                    if not isNull(scr) then
                        local price = scr:GetItemsCost()
                        self._buyCb(price, self._curBuyNum)
                    else 
                        self._buyCb()
                    end
                end
                self:OnBtnClose()
            end,
            nil,
            subTitle
    )
end

function UICommonBuyItemDialog:GetMaxBuyNum()
    if self._coinPrices then
        local scr = self:GetExchangeMaterialNodeScr()
        if not isNull(scr) then
            return math.min(scr:GetMaxBuyNum(), self._maxBuyNum)
        end
    end

    local maxNum = self._maxBuyNum

    if self._consumeGoodsId > 0 then
        local haveNum = GoodsUtils.GetThingNo(self._consumeGoodsId)
        local num = math.floor(haveNum / self._consumeNum)
        maxNum = math.min(maxNum, num)
        return maxNum
    end
    
    local payMaxNum = 0
    for _, v in ipairs(self._prices) do
        local haveNum = GoodsUtils.GetThingNo(v.currency)
        local num = math.floor(haveNum / v.current)
        payMaxNum = math.max(payMaxNum, num)
    end
    maxNum = math.min(maxNum, payMaxNum)
    return maxNum
end

---跳转事件处理
function UICommonBuyItemDialog:ExecuteJumpEventHandler()
    self:OnBtnClose()
end

return UICommonBuyItemDialog